mapper.sql:
SELECT soi.id AS orderItemId, so.id AS orderId, so.platform_order_id AS platformOrderId, so.platform AS platform, so.order_time AS orderTime, so.shop_id AS shopId, soi.platform_order_item_id AS platformOrderItemId, soi.platform_sku AS platformSku, soi.product_name AS productName, soi.sku_id AS skuId, soi.quantity AS quantity, soi.item_amount AS itemAmount, soi.currency AS currency FROM shop_order_item soi JOIN shop_order so ON soi.order_id = so.id
so.order_status IN ('WAIT_SHIP', 'SHIPPED', 'COMPLETED')
AND so.shop_id = #{shopId}
AND so.platform = #{platform}
AND soi.sku_id = #{skuId}
AND so.order_time >= #{dateFrom}
AND so.order_time < #{dateTo}
ORDER BY so.order_time DESC, soi.id DESC
